// src/pages/Schemes.jsx
// ✅ Full Tamil & Hindi translation — no i18n dependency

import { useState } from "react";
import C from "../constants/colors";
import { SCHEMES } from "../constants/data";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";

// ── Inline Strings ────────────────────────────────────────────────────────────
const STRINGS = {
  en: {
    title:       "Government Schemes",
    subtitle:    "Central & Tamil Nadu agricultural schemes",
    available:   "schemes available",
    eligibility: "Eligibility Criteria",
    documents:   "Required Documents",
    apply:       "Apply →",
    portal:      "Portal",
    active:      "Active",
    yourProfile: "Your profile",
    acres:       "acres",
    various:     "various crops",
    central:     "Central",
    state:       "State",
    noSchemes:   "No schemes available",
  },
  ta: {
    title:       "அரசு திட்டங்கள்",
    subtitle:    "மத்திய & தமிழ்நாடு வேளாண் திட்டங்கள்",
    available:   "திட்டங்கள் கிடைக்கின்றன",
    eligibility: "தகுதி அளவுகோல்கள்",
    documents:   "தேவையான ஆவணங்கள்",
    apply:       "விண்ணப்பிக்க →",
    portal:      "இணையதளம்",
    active:      "செயலில் உள்ளது",
    yourProfile: "உங்கள் சுயவிவரம்",
    acres:       "ஏக்கர்",
    various:     "பல்வேறு பயிர்கள்",
    central:     "மத்திய",
    state:       "மாநில",
    noSchemes:   "திட்டங்கள் எதுவும் இல்லை",
  },
  hi: {
    title:       "सरकारी योजनाएं",
    subtitle:    "केंद्र और तमिलनाडु कृषि योजनाएं",
    available:   "योजनाएं उपलब्ध हैं",
    eligibility: "पात्रता मानदंड",
    documents:   "आवश्यक दस्तावेज",
    apply:       "आवेदन करें →",
    portal:      "पोर्टल",
    active:      "सक्रिय",
    yourProfile: "आपकी प्रोफ़ाइल",
    acres:       "एकड़",
    various:     "विभिन्न फसलें",
    central:     "केंद्रीय",
    state:       "राज्य",
    noSchemes:   "कोई योजना उपलब्ध नहीं",
  },
};

// ── Scheme content translations ───────────────────────────────────────────────
// Each scheme: { name, tag, amount, desc, eligibility, docs, portal }
const SCHEME_TRANSLATIONS = {
  ta: [
    {
      name:        "PM-KISAN",
      tag:         "மத்திய",
      amount:      "₹6,000/ஆண்டு",
      desc:        "சிறு மற்றும் குறு விவசாயிகளுக்கு ஆண்டுதோறும் ₹6,000 நேரடி வருமான ஆதரவு மூன்று தவணைகளில் வழங்கப்படுகிறது.",
      eligibility: "2 ஹெக்டேர் வரை விளை நிலம் கொண்ட அனைத்து விவசாயக் குடும்பங்களும் தகுதியுடையவர்கள்.",
      docs:        ["ஆதார் அட்டை", "வங்கி பாஸ்புக்", "நில பத்திர ஆவணங்கள்", "மொபைல் எண்"],
      portal:      "https://pmkisan.gov.in",
    },
    {
      name:        "PM பயிர் காப்பீட்டு திட்டம்",
      tag:         "மத்திய",
      amount:      "மானியம் பெற்ற பிரீமியம்",
      desc:        "இயற்கை பேரழிவு, பூச்சி மற்றும் நோயால் பயிர் இழப்பு ஏற்படும்போது விவசாயிகளுக்கு நிதி ஆதரவு அளிக்கிறது.",
      eligibility: "அறிவிக்கப்பட்ட பகுதிகளில் அறிவிக்கப்பட்ட பயிர்களை பயிரிடும் அனைத்து விவசாயிகளும்.",
      docs:        ["நில பத்திர ஆவணங்கள்", "விதைப்பு சான்றிதழ்", "வங்கி கணக்கு", "ஆதார் அட்டை"],
      portal:      "https://pmfby.gov.in",
    },
    {
      name:        "கிசான் கடன் அட்டை",
      tag:         "மத்திய",
      amount:      "3 லட்சம் வரை கடன்",
      desc:        "விவசாயிகளுக்கு குறைந்த வட்டியில் பயிர் கடன் மற்றும் தோட்டக்கலை தேவைகளுக்கு நெகிழ்வான கடன் வழங்குகிறது.",
      eligibility: "நில உரிமையாளர் விவசாயிகள், குத்தகைதாரர்கள் மற்றும் பகிர்வு விவசாயிகள்.",
      docs:        ["ஆதார் அட்டை", "நில பத்திர ஆவணங்கள்", "பாஸ்போர்ட் புகைப்படம்", "வங்கி அறிக்கை"],
      portal:      "https://www.nabard.org",
    },
    {
      name:        "தமிழ்நாடு வேளாண் உதவித்தொகை",
      tag:         "மாநில",
      amount:      "பல்வேறு மானியங்கள்",
      desc:        "தமிழ்நாடு விவசாயிகளுக்கு விதை, உரம், பயிர்ப்பாதுகாப்பு மற்றும் விவசாய இயந்திரங்களுக்கு மானியம்.",
      eligibility: "தமிழ்நாட்டில் பதிவுசெய்யப்பட்ட விவசாயிகள் மற்றும் குத்தகைதாரர்கள்.",
      docs:        ["சிட்டா & அடங்கல்", "ஆதார் அட்டை", "விவசாயி பதிவு அட்டை", "வங்கி பாஸ்புக்"],
      portal:      "https://www.tn.gov.in/scheme/data_view/6898",
    },
    {
      name:        "PM-KUSUM",
      tag:         "மத்திய",
      amount:      "90% மானியம்",
      desc:        "விவசாயிகளுக்கு சோலார் பம்புகள் நிறுவ 90% மானியம் வழங்கி நீர்ப்பாசன செலவை குறைக்கிறது.",
      eligibility: "தனி விவசாயிகள், பஞ்சாயத்துக்கள், கூட்டுறவு சங்கங்கள் மற்றும் நீர்ப்பாசன சங்கங்கள்.",
      docs:        ["ஆதார் அட்டை", "நில பத்திர ஆவணங்கள்", "வங்கி கணக்கு விவரங்கள்", "மின்சார இணைப்பு"],
      portal:      "https://pmkusum.mnre.gov.in",
    },
    {
      name:        "தேசிய வேளாண் சந்தை (eNAM)",
      tag:         "மத்திய",
      amount:      "நேரடி சந்தை அணுகல்",
      desc:        "விவசாயிகளை நேரடியாக வாங்குவோருடன் இணைக்கும் ஒருங்கிணைந்த மின்னணு வர்த்தக தளம்.",
      eligibility: "eNAM-ல் பதிவுசெய்யப்பட்ட APMC மண்டிகளில் உள்ள அனைத்து விவசாயிகளும்.",
      docs:        ["ஆதார் அட்டை", "வங்கி கணக்கு", "மொபைல் எண்", "பயிர் விவரங்கள்"],
      portal:      "https://enam.gov.in",
    },
  ],
  hi: [
    {
      name:        "पीएम-किसान",
      tag:         "केंद्रीय",
      amount:      "₹6,000/वर्ष",
      desc:        "छोटे और सीमांत किसानों को वार्षिक ₹6,000 की प्रत्यक्ष आय सहायता तीन किस्तों में दी जाती है।",
      eligibility: "2 हेक्टेयर तक कृषि योग्य भूमि वाले सभी किसान परिवार पात्र हैं।",
      docs:        ["आधार कार्ड", "बैंक पासबुक", "भूमि दस्तावेज", "मोबाइल नंबर"],
      portal:      "https://pmkisan.gov.in",
    },
    {
      name:        "पीएम फसल बीमा योजना",
      tag:         "केंद्रीय",
      amount:      "सब्सिडी प्रीमियम",
      desc:        "प्राकृतिक आपदा, कीट और रोग से फसल नुकसान पर किसानों को वित्तीय सहायता।",
      eligibility: "अधिसूचित क्षेत्रों में अधिसूचित फसलें उगाने वाले सभी किसान।",
      docs:        ["भूमि दस्तावेज", "बुवाई प्रमाण पत्र", "बैंक खाता", "आधार कार्ड"],
      portal:      "https://pmfby.gov.in",
    },
    {
      name:        "किसान क्रेडिट कार्ड",
      tag:         "केंद्रीय",
      amount:      "3 लाख तक ऋण",
      desc:        "किसानों को कम ब्याज पर फसल ऋण और बागवानी जरूरतों के लिए लचीला ऋण।",
      eligibility: "भूमि स्वामी किसान, किरायेदार और बटाईदार किसान।",
      docs:        ["आधार कार्ड", "भूमि दस्तावेज", "पासपोर्ट फोटो", "बैंक स्टेटमेंट"],
      portal:      "https://www.nabard.org",
    },
    {
      name:        "तमिलनाडु कृषि सब्सिडी",
      tag:         "राज्य",
      amount:      "विभिन्न सब्सिडी",
      desc:        "तमिलनाडु किसानों के लिए बीज, उर्वरक, फसल सुरक्षा और कृषि मशीनरी पर सब्सिडी।",
      eligibility: "तमिलनाडु में पंजीकृत किसान और किरायेदार।",
      docs:        ["भूमि दस्तावेज", "आधार कार्ड", "किसान पंजीकरण कार्ड", "बैंक पासबुक"],
      portal:      "https://www.tn.gov.in/scheme/data_view/6898",
    },
    {
      name:        "पीएम-कुसुम",
      tag:         "केंद्रीय",
      amount:      "90% सब्सिडी",
      desc:        "किसानों को सोलर पंप लगाने पर 90% सब्सिडी देकर सिंचाई लागत कम करना।",
      eligibility: "व्यक्तिगत किसान, पंचायत, सहकारी समितियां और जल उपयोगकर्ता संघ।",
      docs:        ["आधार कार्ड", "भूमि दस्तावेज", "बैंक खाता विवरण", "बिजली कनेक्शन"],
      portal:      "https://pmkusum.mnre.gov.in",
    },
    {
      name:        "राष्ट्रीय कृषि बाजार (eNAM)",
      tag:         "केंद्रीय",
      amount:      "प्रत्यक्ष बाजार पहुंच",
      desc:        "किसानों को सीधे खरीदारों से जोड़ने वाला एकीकृत इलेक्ट्रॉनिक ट्रेडिंग प्लेटफॉर्म।",
      eligibility: "eNAM में पंजीकृत APMC मंडियों के सभी किसान।",
      docs:        ["आधार कार्ड", "बैंक खाता", "मोबाइल नंबर", "फसल विवरण"],
      portal:      "https://enam.gov.in",
    },
  ],
};

// ─────────────────────────────────────────────────────────────────────────────
function Schemes({ user, t, lang }) {
  const [open, setOpen] = useState(null);

  const S = STRINGS[lang] || STRINGS.en;

  // ── Safe data ─────────────────────────────────────────────────────────────
  const baseSchemes = Array.isArray(SCHEMES) ? SCHEMES : [];
  const userCrops   = Array.isArray(user?.crops) ? user.crops : [];

  // ── Pick translated scheme content or fall back to base data ─────────────
  const schemeTx = SCHEME_TRANSLATIONS[lang];
  const schemes  = baseSchemes.map((s, i) => ({
    ...s,
    ...(schemeTx?.[i] || {}),      // overlay translation if exists
  }));

  return (
    <div style={{ padding: 22 }}>
      <h1 style={{ fontSize: 21, fontWeight: 600, color: C.text, margin: "0 0 4px" }}>
        🏛️ {S.title}
      </h1>
      <p style={{ color: C.muted, fontSize: 13, margin: "0 0 6px" }}>{S.subtitle}</p>

      {/* ── Profile banner ────────────────────────────────────────────────── */}
      <div style={{
        padding: "10px 14px", background: C.pale,
        borderRadius: 8, fontSize: 13, color: C.bg2, marginBottom: 16,
      }}>
        ✅ {S.yourProfile}: <strong>{user?.name}</strong> • {user?.district} •{" "}
        {user?.landSize || "?"} {S.acres} •{" "}
        {userCrops.slice(0, 3).join(", ") || S.various} —{" "}
        <strong>{schemes.length} {S.available}</strong>
      </div>

      {/* ── Scheme list ───────────────────────────────────────────────────── */}
      {schemes.length === 0 && (
        <div style={{ textAlign: "center", color: C.muted, fontSize: 13, padding: 32 }}>
          {S.noSchemes}
        </div>
      )}

      {schemes.map((s, i) => (
        <Card key={i} style={{ marginBottom: 10 }}>
          <div
            style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", cursor: "pointer" }}
            onClick={() => setOpen(open === i ? null : i)}
          >
            <div style={{ flex: 1, marginRight: 14 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4, flexWrap: "wrap" }}>
                <span style={{ fontSize: 14.5, fontWeight: 600, color: C.text }}>{s.name}</span>
                <Badge>{s.tag}</Badge>
                <Badge color={C.amber} bg={C.amberPale}>{s.amount}</Badge>
              </div>
              <div style={{ fontSize: 13, color: C.muted, lineHeight: 1.45 }}>{s.desc}</div>
            </div>

            <div style={{ display: "flex", flexDirection: "column", gap: 7, alignItems: "flex-end", flexShrink: 0 }}>
              <Badge color={C.bg2}>● {S.active}</Badge>
              <button
                onClick={e => { e.stopPropagation(); window.open(s.portal, "_blank"); }}
                style={{
                  padding: "6px 13px", background: C.bg2, color: "#fff",
                  borderRadius: 7, border: "none", cursor: "pointer",
                  fontSize: 12, fontWeight: 500,
                }}
              >
                {S.apply}
              </button>
            </div>
          </div>

          {/* ── Expanded details ─────────────────────────────────────────── */}
          {open === i && (
            <div style={{ marginTop: 12, paddingTop: 12, borderTop: `1px solid ${C.border}` }}>

              {/* Eligibility */}
              <div style={{ marginBottom: 10, padding: "10px 12px", background: C.pale, borderRadius: 8 }}>
                <div style={{ fontSize: 12.5, fontWeight: 600, color: C.text, marginBottom: 4 }}>
                  ✅ {S.eligibility}:
                </div>
                <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.5 }}>{s.eligibility}</div>
              </div>

              {/* Documents */}
              <div style={{ fontSize: 12.5, fontWeight: 600, color: C.text, marginBottom: 6 }}>
                📄 {S.documents}:
              </div>
              <div style={{ display: "flex", gap: 7, flexWrap: "wrap", marginBottom: 10 }}>
                {(Array.isArray(s.docs) ? s.docs : []).map((d, di) => (
                  <span key={di} style={{
                    padding: "4px 10px", background: C.bg, borderRadius: 6,
                    fontSize: 12, color: C.text, border: `1px solid ${C.border}`,
                  }}>
                    📄 {d}
                  </span>
                ))}
              </div>

              {/* Portal */}
              <div style={{ fontSize: 12, color: C.muted }}>
                🌐 {S.portal}:{" "}
                <a href={s.portal} target="_blank" rel="noreferrer" style={{ color: C.bg2 }}>
                  {s.portal}
                </a>
              </div>
            </div>
          )}
        </Card>
      ))}
    </div>
  );
}

export default Schemes;
